def msg_ref(id, dname=None):
    "Markdown ref to a message — same-dialog `#_id` or cross-dialog `#dname/_id` (anchors target DOM ids, which carry a `_` prefix)"
    id = '_'+_mid(id)
    if not dname: return f'#{id}'
    return f'#{find_dname(dname)}/{id}'

